const app=document.querySelector('#app');
const query=new URLSearchParams(location.search);
const mobile=query.get('surface')==='mobile';
const icon=(name)=>{const paths={down:'m7 10 5 5 5-5',menu:'M4 6h16 M4 12h16 M4 18h16',pc:'M3 3h18v13H3z M8 21h8 M12 16v5',check:'m5 12 4 4 10-10',plus:'M12 4v16 M4 12h16',folder:'M3 7h7l2-3h9v16H3z',book:'M3 4h6a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H3z M21 4h-6a3 3 0 0 0-3 3 M21 4v14h-6a3 3 0 0 0-3 3',more:'M5 12h.01 M12 12h.01 M19 12h.01',back:'m15 4-8 8 8 8',pen:'m5 16-1 5 5-1L21 8l-5-5Z M14 5l5 5',branch:'M6 3v12a4 4 0 0 0 8 0V9 M4 5h4 M12 7h4 M4 18h4',wifi:'M3 9a15 15 0 0 1 18 0 M6 12a10 10 0 0 1 12 0 M9 15a5 5 0 0 1 6 0 M12 19h.01',signal:'M4 17v4 M9 13v8 M14 8v13 M19 3v18',notebook:'M5 3h15v18H5z M2 7h5 M2 12h5 M2 17h5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.menu}"/></svg>`};
let state,open=query.get('connections')==='open';
function trigger() {
  const count = state.connections.filter(c => c.id !== state.activeId).reduce((n, c) => n + c.count, 0);
  const active = state.connections.find(c => c.id === state.activeId);
  return `<button class="connection-trigger" aria-label="切换连接，其他连接 ${count}" aria-expanded="${open}" data-toggle><span class="current-caption">当前连接</span><span>${active.name}</span>${icon('down')}${numericBadge(count, 'desktop-total-badge')}</button>`;
}
function numericBadge(count, extraClass = '') {
  return count > 0 ? `<span class="number-badge ${extraClass}" aria-label="${count}">${count}</span>` : '';
}
function renderMobileHome() {
  const active = state.connections.find(c => c.id === state.activeId);
  const otherCount = state.connections.filter(c => c.id !== state.activeId).reduce((n, c) => n + c.count, 0);
  const pin = '<span class="pin" aria-hidden="true">📌</span>';
  const terminalRow = t => `<div class="home-terminal"><div class="terminal-title-line"><strong>${t.title}${t.hasUnreadCompletion ? '<i class="completion-dot" aria-label="有新的完成结果"></i>' : ''}</strong>${pin}<span class="task-state ${t.running ? 'running' : 'idle'}"><i class="dot"></i>${t.state}</span></div><div class="terminal-project">${t.project}</div><p>最近输入：${t.input}</p><p>最近回复：${t.reply}</p></div>`;
  const gear = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 3-.7 2.1-2 .9-2-.4L2 9l1.5 1.7v2.6L2 15l2.3 3.4 2-.4 2 .9L9 21h6l.7-2.1 2-.9 2 .4L22 15l-1.5-1.7v-2.6L22 9l-2.3-3.4-2 .4-2-.9L15 3Z"/><circle cx="12" cy="12" r="3"/></svg>';
  const info = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6 M12 7h.01"/></svg>';
  const search = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg>';
  app.className = 'app mobile home badge-prototype';
  app.innerHTML = `
    <div class="native-status"><span>8:39</span><span class="dynamic-island"></span><div class="status-icons">${icon('signal')}${icon('wifi')}<span class="battery"></span></div></div>
    <nav class="home-toolbar">
      <button class="home-current" aria-label="切换连接，其他连接 ${otherCount}" aria-expanded="${open}" data-toggle>
        <i class="dot"></i><span class="active-name">${active.name}</span><span class="device-battery"><span class="battery"></span>100%</span>${icon('down')}${numericBadge(otherCount, 'total-badge')}
      </button>
      <div class="home-actions"><button aria-label="设置">${gear}</button><button aria-label="首页操作">${icon('more')}</button></div>
    </nav>
    <div class="home-list">
      <section class="home-section home-attention" aria-label="关注"><header class="home-section-header"><h2>关注</h2></header><div class="home-group">${state.homeAttention.map(terminalRow).join('')}</div></section>
      <section class="home-section"><header class="home-group-header">${icon('down')}<div><strong>browser-viewer</strong><small>~/Code/browser-viewer</small></div><span class="project-count">3</span><button aria-label="创建终端">+</button></header><div class="home-group">${terminalRow({title:'项目整理',project:'browser-viewer · main',state:'空闲',running:false,hasUnreadCompletion:false,input:'查看一下当前工作区的变更。',reply:'当前工作区没有待提交的代码变更。'})}</div></section>
    </div>
    <div class="native-search" role="search">${search}<span>Search projects and terminals</span></div>
    <div class="bottom-project">✦　 自进化</div>
    ${open ? `<div class="sheet-backdrop" data-dismiss></div>` : ''}
    <section class="connection-menu connection-sheet" role="dialog" aria-modal="true" aria-label="切换连接" ${open ? '' : 'hidden'}>
      <div class="sheet-handle"></div>
      <header class="sheet-header"><span></span><strong>切换连接</strong><button data-dismiss aria-label="关闭连接列表">关闭</button></header>
      <div class="sheet-list">${state.connections.map(c => `<div class="picker-row"><button class="connection-row ${c.id === state.activeId ? 'active' : ''}" data-select="${c.id}">${icon('pc')}<span class="connection-label">${c.name}<small>${c.id === state.activeId ? '当前 · 已登录' : c.online ? '已连接' : '离线 · 上次同步'}</small></span>${numericBadge(c.count)}${c.id === state.activeId ? `<span class="selected-check">${icon('check')}</span>` : ''}</button><button class="connection-info" aria-label="查看 ${c.name} 连接详情">${info}</button></div>`).join('')}</div>
      <button class="add-connection">${icon('plus')}<span>添加连接<small>扫码连接电脑或手动添加</small></span></button>
    </section>
    <div class="home-indicator"></div>`;
}
function render(){if(mobile){renderMobileHome();return;}const active=state.connections.find(c=>c.id===state.activeId);app.className='app desktop';app.innerHTML=`<div class="native-status"><span>9:41</span><div class="status-icons">${icon('signal')}${icon('wifi')}<span class="battery"></span></div></div><nav class="native-toolbar"><button class="square" aria-label="返回">${icon('back')}</button><div class="native-title"><strong>修复构建 <span>/ Runweave</span></strong><small><i class="dot"></i>${active.name} · 已连接</small></div><button class="square" aria-label="终端文件">${icon('folder')}</button><button class="square" aria-label="更多">${icon('more')}</button></nav><div class="mobile-switcher"><span class="mobile-active">${icon('pc')}当前连接 · ${active.name}</span>${trigger(true)}</div><nav class="mobile-tabs"><button class="active">Chat</button><button>Files</button><button>Changes</button></nav><header class="header"><button class="square" aria-label="应用菜单">${icon('menu')}</button>${trigger()}<nav class="projects"><button class="project selected">Runweave</button><button class="project">随记</button><button class="square" aria-label="添加项目">${icon('plus')}</button></nav><div class="tools"><button class="read">${icon('book')}阅读会话</button><button class="square">${icon('notebook')}</button><button class="square">${icon('clock')}</button><button class="square">${icon('more')}</button></div></header><div class="workspace"><aside class="rail"><div class="rail-label">WORKTREES <span>＋</span></div><div class="context">browser-viewer<div class="branch">${icon('branch')}main</div></div><div class="context selected">wt-1<div class="branch">${icon('branch')}feature/build-fix</div></div><div class="context">wt-2<div class="branch">${icon('branch')}feature/terminal</div></div></aside><section class="stage"><nav class="sessionbar"><button class="session selected"><i class="dot"></i>修复构建</button><button class="session">项目整理</button><button class="square">${icon('plus')}</button></nav><article class="term"><div class="welcome"><strong>›_ OpenAI Codex</strong><p>model: gpt-6.1</p><p>directory: ~/Code/browser-viewer/.worktree/wt-1</p></div><p class="prompt"><span class="symbol">›</span>检查一下构建失败的原因，修复后再验证。</p><p class="assistant">我会先检查构建日志和相关配置，确认失败原因。</p><div class="codeblock">• Exploring<br>  └ Read package.json<br>  └ Read build configuration<br>  └ Search <span class="file">build</span> in scripts/</div><p class="assistant">已定位到构建入口，正在核对依赖和输出目录。</p><div class="working"><span>✳</span> Working <span style="color:#64748b">· 24s</span></div></article><div class="terminal-input"><span>›</span><span style="color:#475569">继续输入…</span></div><footer class="footer"><span>gpt-6.1 · ${active.name}</span><span>87% context left</span></footer></section></div><section class="connection-menu" role="menu" aria-label="切换连接" ${open?'':'hidden'}><div class="menu-title">切换连接</div>${state.connections.map(c=>`<button role="menuitem" data-select="${c.id}" class="connection-row ${c.id===state.activeId?'active':''}">${icon('pc')}<span class="connection-label">${c.name}<small>${c.id===state.activeId?'当前连接':c.online?'已连接':'离线 · 上次同步'}</small></span>${numericBadge(c.count, 'desktop-row-badge')}${c.id===state.activeId?'<span class="check">'+icon('check')+'</span>':''}</button>`).join('')}<div class="menu-divider"></div><button class="menu-utility" role="menuitem">${icon('plus')}连接管理</button></section><button class="compose" aria-label="打开终端输入">${icon('pen')}</button><div class="home-indicator"></div>`;}
fetch('./mock-state.json').then(r=>r.json()).then(value=>{state=value;if(query.get('pending')==='none'){state.connections.filter(c=>c.id!==state.activeId).forEach(c=>{c.count=0;});}render();app.addEventListener('click',e=>{if(e.target.closest('[data-dismiss]')){open=false;render();return}const toggle=e.target.closest('[data-toggle]');if(toggle){open=!open;render();return}const selected=e.target.closest('[data-select]');if(selected){state.activeId=selected.dataset.select;open=false;render();return}if(open&&!e.target.closest('.connection-menu')){open=false;render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&open){open=false;render()}})});
